#include <stdio.h>
#include <string.h>
#include "esp_log.h"
#include "lvgl.h"
#include "ui.h"
#include "ui_gauge.h"

static const char *TAG = "ui";

#define QR_SIZE     240
#define QR_BORDER   12

/* Fonts generated by tools/mkfont.py (Montserrat Medium) */
LV_FONT_DECLARE(font_weight_128);   /* " -.0123456789", tabular digits */
LV_FONT_DECLARE(font_unit_36);      /* " a-z" */
LV_FONT_DECLARE(font_name_32);      /* ASCII + Czech diacritics + degree sign */

/* Keg panel: nearly full screen, corners stay inside the round display */
#define PANEL_W         420
#define PANEL_PAD_V     24          /* height follows the content */
#define PANEL_RADIUS    44
#define PANEL_BG        0xF0F0F0    /* white-gray */
#define PANEL_BORDER    0x909090
#define PANEL_TEXT      0x202020

#define LEVEL_FULL_MS   3000        /* gauge 0 -> 100 % animation time */

static lv_obj_t *s_gauge;
static int32_t s_level;             /* gauge level currently drawn */
static int32_t s_level_target;

/* keg screen labels, NULL on other screens */
static lv_obj_t *s_name, *s_value, *s_unit;

/* Clean screen with the beer gauge as background (at the current level). */
static lv_obj_t *new_screen(void)
{
    lv_obj_t *scr = lv_screen_active();
    lv_obj_clean(scr);
    s_name = s_value = s_unit = NULL;
    lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);    /* scrolling would block swipes */
    lv_obj_set_style_bg_color(scr, lv_color_black(), 0);
    s_gauge = ui_gauge_create(scr);
    ui_gauge_set_level(s_gauge, s_level);
    return scr;
}

/* Animation runs on s_level, not on the gauge object, so it survives
 * screen rebuilds; it always draws into whatever gauge exists now. */
static void level_anim_cb(void *var, int32_t v)
{
    s_level = v;
    if (s_gauge)
        ui_gauge_set_level(s_gauge, v);
}

void ui_set_level(int pct)
{
    if (pct < 0)
        pct = 0;
    else if (pct > 100)
        pct = 100;
    if (pct == s_level_target)
        return;
    s_level_target = pct;

    lv_anim_delete(&s_level, level_anim_cb);
    lv_anim_t a;
    lv_anim_init(&a);
    lv_anim_set_var(&a, &s_level);
    lv_anim_set_exec_cb(&a, level_anim_cb);
    lv_anim_set_values(&a, s_level, pct);
    lv_anim_set_duration(&a, LEVEL_FULL_MS * LV_ABS(pct - s_level) / 100 + 1);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
    lv_anim_start(&a);
}

static lv_obj_t *new_label(lv_obj_t *parent, const char *text, const lv_font_t *font)
{
    lv_obj_t *l = lv_label_create(parent);
    lv_label_set_text(l, text);
    lv_obj_set_style_text_color(l, lv_color_black(), 0);   /* bright background */
    lv_obj_set_style_text_font(l, font, 0);
    return l;
}

/* Escape \ ; , : " for the WIFI: QR payload. Returns length written. */
static size_t wifi_qr_escape(char *dst, size_t n, const char *src)
{
    size_t i = 0;
    for (; *src && i + 2 < n; src++) {
        if (strchr("\\;,:\"", *src))
            dst[i++] = '\\';
        dst[i++] = *src;
    }
    dst[i] = '\0';
    return i;
}

/* Rounded, bordered white-gray box; children stacked and centred. */
static lv_obj_t *new_panel(lv_obj_t *parent)
{
    lv_obj_t *p = lv_obj_create(parent);
    lv_obj_remove_flag(p, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_size(p, PANEL_W, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_color(p, lv_color_hex(PANEL_BG), 0);
    lv_obj_set_style_bg_opa(p, LV_OPA_90, 0);
    lv_obj_set_style_border_color(p, lv_color_hex(PANEL_BORDER), 0);
    lv_obj_set_style_border_width(p, 4, 0);
    lv_obj_set_style_radius(p, PANEL_RADIUS, 0);
    lv_obj_set_style_pad_hor(p, 0, 0);
    lv_obj_set_style_pad_ver(p, PANEL_PAD_V, 0);
    lv_obj_set_style_pad_row(p, 6, 0);
    lv_obj_set_flex_flow(p, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(p, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    return p;
}

void ui_show_keg(void)
{
    lv_obj_t *scr = new_screen();
    lv_obj_t *panel = new_panel(scr);
    lv_obj_center(panel);

    /* keg name (tapped only), value (weight or beers left), unit */
    s_name = new_label(panel, "", &font_name_32);
    lv_obj_set_width(s_name, PANEL_W - 48);
    lv_obj_set_style_text_align(s_name, LV_TEXT_ALIGN_CENTER, 0);
    lv_label_set_long_mode(s_name, LV_LABEL_LONG_SCROLL_CIRCULAR);
    lv_obj_add_flag(s_name, LV_OBJ_FLAG_HIDDEN);

    s_value = new_label(panel, "---", &font_weight_128);
    s_unit = new_label(panel, "", &font_unit_36);

    lv_obj_set_style_text_color(s_name, lv_color_hex(PANEL_TEXT), 0);
    lv_obj_set_style_text_color(s_value, lv_color_hex(PANEL_TEXT), 0);
    lv_obj_set_style_text_color(s_unit, lv_color_hex(PANEL_TEXT), 0);
}

static void set_text(lv_obj_t *l, const char *text)
{
    if (strcmp(lv_label_get_text(l), text) != 0)
        lv_label_set_text(l, text);
}

void ui_keg_update(const scale_data_t *d)
{
    if (!s_value)
        return;

    bool keg = d->keg.tapped;
    char buf[16];
    snprintf(buf, sizeof(buf), "%.1f", keg ? d->keg_left : d->units);
    set_text(s_value, buf);
    set_text(s_unit, keg ? d->calib.usec : d->calib.uprim);

    if (keg) {
        set_text(s_name, d->keg.name);
        lv_obj_remove_flag(s_name, LV_OBJ_FLAG_HIDDEN);
    } else {
        lv_obj_add_flag(s_name, LV_OBJ_FLAG_HIDDEN);
    }
}

/* New screen with a centred QR code (white quiet zone) and two labels below. */
static void show_qr(const char *payload, const char *title, const char *subtitle)
{
    lv_obj_t *scr = new_screen();

    lv_obj_t *qr = lv_qrcode_create(scr);
    lv_qrcode_set_size(qr, QR_SIZE);
    lv_qrcode_set_dark_color(qr, lv_color_black());
    lv_qrcode_set_light_color(qr, lv_color_white());
    if (lv_qrcode_update(qr, payload, strlen(payload)) != LV_RESULT_OK)
        ESP_LOGE(TAG, "qr encode failed");
    lv_obj_set_style_border_color(qr, lv_color_white(), 0);
    lv_obj_set_style_border_width(qr, QR_BORDER, 0);
    lv_obj_align(qr, LV_ALIGN_CENTER, 0, -30);

    lv_obj_t *l_title = new_label(scr, title, &lv_font_montserrat_32);
    lv_obj_align_to(l_title, qr, LV_ALIGN_OUT_BOTTOM_MID, 0, 14);

    lv_obj_t *l_sub = new_label(scr, subtitle, &lv_font_montserrat_16);
    lv_obj_align_to(l_sub, l_title, LV_ALIGN_OUT_BOTTOM_MID, 0, 6);
}

void ui_show_ap(const char *ssid, const char *password, const char *ip)
{
    char s[2 * 32 + 1], p[2 * 64 + 1], payload[sizeof(s) + sizeof(p) + 24];
    wifi_qr_escape(s, sizeof(s), ssid);
    wifi_qr_escape(p, sizeof(p), password);
    snprintf(payload, sizeof(payload), "WIFI:T:WPA;S:%s;P:%s;;", s, p);
    show_qr(payload, ssid, ip);
}

void ui_show_webi(const char *ip)
{
    if (!ip) {
        lv_obj_t *scr = new_screen();
        lv_obj_center(new_label(scr, "No network", &lv_font_montserrat_32));
        return;
    }
    char url[32];
    snprintf(url, sizeof(url), "http://%s/", ip);
    show_qr(url, "Web", url);
}
